CREATE TABLE IF NOT EXISTS users (id BIGSERIAL PRIMARY KEY, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS seller_applications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE REFERENCES users(id), store_name VARCHAR(150) NOT NULL, phone VARCHAR(20) NOT NULL, city VARCHAR(100) NOT NULL, district VARCHAR(100) NOT NULL, description VARCHAR(1000), status VARCHAR(20) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), applied_at TIMESTAMP NOT NULL DEFAULT now(), reviewed_at TIMESTAMP);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS logo_url VARCHAR(2048);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS whatsapp_phone VARCHAR(20);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS contact_email VARCHAR(150);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS street_address VARCHAR(500);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS latitude NUMERIC(9,6);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS longitude NUMERIC(9,6);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS working_hours JSONB;
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS website_url VARCHAR(2048);
ALTER TABLE seller_applications ADD COLUMN IF NOT EXISTS profile_active BOOLEAN NOT NULL DEFAULT TRUE;
CREATE TABLE IF NOT EXISTS products (id BIGSERIAL PRIMARY KEY, seller_id BIGINT NOT NULL REFERENCES seller_applications(id), name VARCHAR(200) NOT NULL, description VARCHAR(4000), category VARCHAR(100) NOT NULL, brand VARCHAR(100) NOT NULL, oem_number VARCHAR(100), price NUMERIC(12,2) NOT NULL, stock_quantity INTEGER NOT NULL, product_condition VARCHAR(10) NOT NULL, image_url VARCHAR(2048), moderation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), reviewed_at TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_vehicle_compatibilities (id BIGSERIAL PRIMARY KEY, product_id BIGINT REFERENCES products(id), vehicle_brand VARCHAR(100) NOT NULL, vehicle_model VARCHAR(100) NOT NULL, year_from INTEGER NOT NULL, year_to INTEGER NOT NULL, engine_info VARCHAR(150));
ALTER TABLE product_vehicle_compatibilities ADD COLUMN IF NOT EXISTS catalog_product_id BIGINT;
ALTER TABLE product_vehicle_compatibilities ALTER COLUMN product_id DROP NOT NULL;
CREATE TABLE IF NOT EXISTS catalog_products (id BIGSERIAL PRIMARY KEY, name VARCHAR(200) NOT NULL, description VARCHAR(4000), category VARCHAR(100) NOT NULL, brand VARCHAR(100) NOT NULL, oem_number VARCHAR(100), moderation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), reviewed_at TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS product_offers (id BIGSERIAL PRIMARY KEY, seller_id BIGINT NOT NULL REFERENCES seller_applications(id), catalog_product_id BIGINT NOT NULL REFERENCES catalog_products(id), legacy_product_id BIGINT UNIQUE REFERENCES products(id), price NUMERIC(12,2) NOT NULL CHECK(price >= 0), stock_quantity INTEGER NOT NULL CHECK(stock_quantity >= 0), product_condition VARCHAR(10) NOT NULL, moderation_status VARCHAR(20) NOT NULL DEFAULT 'PENDING', rejection_reason VARCHAR(500), reviewed_at TIMESTAMP, active BOOLEAN NOT NULL DEFAULT TRUE, price_updated_at TIMESTAMP NOT NULL DEFAULT now(), stock_updated_at TIMESTAMP NOT NULL DEFAULT now(), created_at TIMESTAMP NOT NULL DEFAULT now(), updated_at TIMESTAMP);
CREATE TABLE IF NOT EXISTS offer_photos (id BIGSERIAL PRIMARY KEY, offer_id BIGINT NOT NULL REFERENCES product_offers(id) ON DELETE CASCADE, object_key VARCHAR(500) NOT NULL UNIQUE, public_url VARCHAR(2048), display_order INTEGER NOT NULL DEFAULT 0, primary_photo BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS user_favorites (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE, catalog_product_id BIGINT NOT NULL REFERENCES catalog_products(id) ON DELETE CASCADE, created_at TIMESTAMP NOT NULL DEFAULT now(), CONSTRAINT uk_favorite_user_catalog UNIQUE(user_id,catalog_product_id));
CREATE TABLE IF NOT EXISTS complaints (id BIGSERIAL PRIMARY KEY, reporter_id BIGINT NOT NULL REFERENCES users(id), seller_id BIGINT NOT NULL REFERENCES seller_applications(id), offer_id BIGINT REFERENCES product_offers(id), category VARCHAR(30) NOT NULL, description VARCHAR(2000) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', admin_note VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT now(), reviewed_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_products_status_active_created ON products(moderation_status,active,created_at);
CREATE INDEX IF NOT EXISTS idx_vehicle_catalog ON product_vehicle_compatibilities(catalog_product_id);
CREATE INDEX IF NOT EXISTS idx_catalog_status_name ON catalog_products(moderation_status,name);
CREATE INDEX IF NOT EXISTS idx_catalog_oem ON catalog_products(oem_number);
CREATE INDEX IF NOT EXISTS idx_offer_catalog_public ON product_offers(catalog_product_id,moderation_status,active,price);
CREATE INDEX IF NOT EXISTS idx_offer_seller_created ON product_offers(seller_id,created_at);
CREATE INDEX IF NOT EXISTS idx_offer_photo_order ON offer_photos(offer_id,display_order);
CREATE INDEX IF NOT EXISTS idx_favorite_user_created ON user_favorites(user_id,created_at);
CREATE INDEX IF NOT EXISTS idx_complaint_status_created ON complaints(status,created_at);
CREATE INDEX IF NOT EXISTS idx_complaint_reporter_created ON complaints(reporter_id,created_at);
